ddl.school.demo:
-- tcxp registry "school.demo" (PostgreSQL)
-- A small learning platform: students enroll in courses, courses publish assignments, students submit work that gets graded.

CREATE TABLE students (
  student_id  integer PRIMARY KEY,
  first_name  text NOT NULL,
  last_name   text NOT NULL,
  email       text NOT NULL UNIQUE,
  cohort      text NOT NULL,
  gpa         numeric(3,2) CHECK (gpa BETWEEN 0 AND 4),
  enrolled_on date NOT NULL
);
COMMENT ON TABLE students IS 'One row per learner. Cohort groups students by intake term.';
COMMENT ON COLUMN students.student_id IS 'Surrogate key.';
COMMENT ON COLUMN students.first_name IS 'Given name.';
COMMENT ON COLUMN students.last_name IS 'Family name.';
COMMENT ON COLUMN students.email IS 'Login and contact address.';
COMMENT ON COLUMN students.cohort IS 'Intake term, e.g. 2026-fall.';
COMMENT ON COLUMN students.gpa IS 'Cumulative grade point average, 0.00 to 4.00.';
COMMENT ON COLUMN students.enrolled_on IS 'Date the student joined the platform.';

CREATE TABLE courses (
  course_id  integer PRIMARY KEY,
  code       text NOT NULL UNIQUE,
  title      text NOT NULL,
  department text NOT NULL,
  credits    integer NOT NULL CHECK (credits > 0)
);
COMMENT ON TABLE courses IS 'Catalog of courses. A course may have no assignments yet.';
COMMENT ON COLUMN courses.course_id IS 'Surrogate key.';
COMMENT ON COLUMN courses.code IS 'Catalog code, e.g. CS101.';
COMMENT ON COLUMN courses.title IS 'Display title.';
COMMENT ON COLUMN courses.department IS 'Owning department.';
COMMENT ON COLUMN courses.credits IS 'Credit hours.';

CREATE TABLE enrollments (
  enrollment_id integer PRIMARY KEY,
  student_id    integer NOT NULL REFERENCES students(student_id),
  course_id     integer NOT NULL REFERENCES courses(course_id),
  enrolled_at   date NOT NULL,
  status        text NOT NULL CHECK (status IN ('active','dropped','completed'))
);
COMMENT ON TABLE enrollments IS 'Bridge table: which student is in which course, and their status.';
COMMENT ON COLUMN enrollments.enrollment_id IS 'Surrogate key.';
COMMENT ON COLUMN enrollments.student_id IS 'Enrolled student.';
COMMENT ON COLUMN enrollments.course_id IS 'Course enrolled in.';
COMMENT ON COLUMN enrollments.enrolled_at IS 'Date of enrollment.';
COMMENT ON COLUMN enrollments.status IS 'Lifecycle state.';

CREATE TABLE assignments (
  assignment_id integer PRIMARY KEY,
  course_id     integer REFERENCES courses(course_id),
  title         text NOT NULL,
  max_points    integer NOT NULL,
  due_on        date
);
COMMENT ON TABLE assignments IS 'Gradable work. course_id is NULL for items still in the shared assignment bank.';
COMMENT ON COLUMN assignments.assignment_id IS 'Surrogate key.';
COMMENT ON COLUMN assignments.course_id IS 'Owning course; NULL while unattached in the bank.';
COMMENT ON COLUMN assignments.title IS 'Display title.';
COMMENT ON COLUMN assignments.max_points IS 'Maximum achievable score.';
COMMENT ON COLUMN assignments.due_on IS 'Due date; NULL for bank items.';

CREATE TABLE submissions (
  submission_id integer PRIMARY KEY,
  assignment_id integer NOT NULL REFERENCES assignments(assignment_id),
  student_id    integer NOT NULL REFERENCES students(student_id),
  submitted_at  timestamptz NOT NULL,
  score         numeric(5,2),
  status        text NOT NULL CHECK (status IN ('on_time','late','resubmitted'))
);
COMMENT ON TABLE submissions IS 'One row per submitted attempt. score is NULL until graded.';
COMMENT ON COLUMN submissions.submission_id IS 'Surrogate key.';
COMMENT ON COLUMN submissions.assignment_id IS 'Assignment submitted against.';
COMMENT ON COLUMN submissions.student_id IS 'Submitting student.';
COMMENT ON COLUMN submissions.submitted_at IS 'When the work arrived.';
COMMENT ON COLUMN submissions.score IS 'Points awarded; NULL until graded.';
COMMENT ON COLUMN submissions.status IS 'Timeliness of the submission.';

