ddl.firm.demo:
-- tcxp registry "firm.demo" (PostgreSQL)
-- A consulting firm: employees log hours against client projects. Projects are booked to a July–June fiscal year; tax returns use the calendar year.

CREATE TABLE employees (
  employee_id  integer PRIMARY KEY,
  full_name    text NOT NULL,
  home_country text NOT NULL
);
COMMENT ON TABLE employees IS 'One row per person. home_country is where they are based, not where they worked.';
COMMENT ON COLUMN employees.employee_id IS 'Surrogate key.';
COMMENT ON COLUMN employees.full_name IS 'Display name.';
COMMENT ON COLUMN employees.home_country IS 'ISO country code of the home office.';

CREATE TABLE projects (
  project_id  integer PRIMARY KEY,
  code        text NOT NULL UNIQUE,
  client      text NOT NULL,
  fiscal_year integer NOT NULL
);
COMMENT ON TABLE projects IS 'Client engagements. fiscal_year names the fiscal year (July 1 to June 30) the project is booked to, named for the year it ends.';
COMMENT ON COLUMN projects.project_id IS 'Surrogate key.';
COMMENT ON COLUMN projects.code IS 'Project code, e.g. P-ATLAS.';
COMMENT ON COLUMN projects.client IS 'Client name.';
COMMENT ON COLUMN projects.fiscal_year IS 'Company fiscal year, July–June, named for the year it ends. FY2025 = 2024-07-01 to 2025-06-30.';

CREATE TABLE work_logs (
  log_id       integer PRIMARY KEY,
  employee_id  integer NOT NULL REFERENCES employees(employee_id),
  project_id   integer NOT NULL REFERENCES projects(project_id),
  worked_on    date NOT NULL,
  hours        numeric(5,2) NOT NULL CHECK (hours > 0),
  work_country text NOT NULL
);
COMMENT ON TABLE work_logs IS 'One row per day of logged work. work_country is where the work was physically performed.';
COMMENT ON COLUMN work_logs.log_id IS 'Surrogate key.';
COMMENT ON COLUMN work_logs.employee_id IS 'Who worked.';
COMMENT ON COLUMN work_logs.project_id IS 'Project the hours are billed to.';
COMMENT ON COLUMN work_logs.worked_on IS 'Calendar date of the work.';
COMMENT ON COLUMN work_logs.hours IS 'Hours worked that day.';
COMMENT ON COLUMN work_logs.work_country IS 'ISO country code where the work was physically performed.';

